// ============================
// 把 AI 给的 order_json 整理成 /api/n8n/wa-order draft 请求体。
// AI 可能带 markdown 围栏或轻微格式偏差，这里做宽容解析；
// 解析不了就带 _parseError 出去，绝不猜。
// ============================

const inp = $input.first().json;
let days;
try {
  let raw = String(inp.order_json || '').trim();
  raw = raw.replace(/^```(json)?/i, '').replace(/```\s*$/i, '').trim();
  const parsed = JSON.parse(raw);
  days = Array.isArray(parsed) ? parsed : [parsed];
} catch (e) {
  return [{ json: { _parseError: 'order_json 不是合法 JSON：' + e.message } }];
}

const body = {
  action: 'draft',
  phone: String(inp.phone || ''),
  customerName: String(inp.customer_name || ''),
  days: days.map(d => ({
    date: String(d.date || ''),
    meal: d.meal === 'dinner' ? 'dinner' : 'lunch',
    ...(d.time ? { time: String(d.time) } : {}),
    items: (Array.isArray(d.items) ? d.items : []).map(it => ({
      dish: it.dish ?? it.name ?? it.dishName ?? '',
      qty: Number(it.qty ?? it.quantity) || 1,
      addOns: (Array.isArray(it.addOns) ? it.addOns : []).map(a => ({
        name: a.name ?? a.label ?? a.id ?? '',
        qty: Number(a.qty ?? a.quantity) || 1
      }))
    }))
  }))
};
const addr = String(inp.address || '').trim();
if (addr) body.address = addr;
const note = String(inp.note || '').trim();
if (note) body.note = note;

return [{ json: { body } }];

// ============================
// API 结果 → 给 AI 的工具返回文本（AI 只能转述这里的数字）
// ============================

const r = $input.first().json || {};

if (r.ok) {
  let text = `✅ 草稿已建立（系统权威计价）\n${r.summaryText || ''}\n应收合计：RM ${Number(r.cashDue).toFixed(2)}（菜品 RM ${Number(r.foodTotal).toFixed(2)} + 运费 RM ${Number(r.deliveryTotal).toFixed(2)}，距离约 ${r.distanceKm}km）`;
  if (r.upsellHint) text += `\n💡 可自然提一句：${r.upsellHint}`;
  if (Array.isArray(r.warnings) && r.warnings.length) text += `\n⚠️ 警告：${r.warnings.join('；')}`;
  if (Array.isArray(r.skippedDays) && r.skippedDays.length) text += `\n⛔ 以下日期无法安排（已剔除）：${r.skippedDays.join('、')}`;
  text += '\n下一步：把明细和合计发给客户确认；客户 OK 后按流程发收款话术 + [SEND_QR]。';
  return [{ json: { result: text } }];
}

const errMsg = (r.error && typeof r.error === 'object') ? (r.error.message || JSON.stringify(r.error)) : (r.error || r.message || '接口无响应');
return [{ json: { result: `❌ 下单草稿失败：${errMsg}。请按原因处理（缺信息就问客户）；拿不准就在回复开头加 [求救老板]。` } }];
